import React, { useEffect, useState } from "react";
import { makeApiRequest } from "../axiosService/ApiCall";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import Web3 from "web3";
import { decryptionKey, encryptData } from "../Auth/SecurityCrypto";
import config from "../axiosService/Config";
import * as bitcoin from 'bitcoinjs-lib';
import * as wif from 'wif';
import { Keypair as SolanaKeypair } from '@solana/web3.js';
import * as bip39 from "bip39";
import bs58 from "bs58";
import * as CardanoWasm from "@emurgo/cardano-serialization-lib-browser";
import { Spinner } from "react-bootstrap";
import ECPairFactory from 'ecpair';
import * as ecc from 'tiny-secp256k1';
import axios from "axios";

bitcoin.initEccLib(ecc);

const ECPair = ECPairFactory(ecc);



function Adminsetting() {
    const [evmAddress, setEvmAddress] = useState("");
    const [evmKey, setEvmKey] = useState("");
    const [btcAddress, setBtcAddress] = useState("");
    const [btcKey, setBtcKey] = useState("");
    const [solAddress, setSolAddress] = useState("");
    const [solKey, setSolKey] = useState("");
    const [ltcAddress, setLtcAddress] = useState("");
    const [ltcKey, setLtcKey] = useState("");
    const [adaAddress, setAdaAddress] = useState("");
    const [adaKey, setAdaKey] = useState("");
    const [loading, setLoading] = useState(true);
    const [loadingStatus, setLoadingStatus] = useState(false);
    const [errors, setErrors] = useState({});
    const [initialSettings, setInitialSettings] = useState({});
    const web3 = new Web3();
    const evmRegex = config.evmRegex;
    const btcRegex = config.btcRegex
    const solRegex = config.solRegex;
    const ltcRegex = config.ltcRegex
    const adaRegex = config.adaRegex

    function getAddressTypeltc(address) {
        // --- TESTNET ---
        if (config.network === "testnet") {
            if (address.startsWith("tltc1p")) return 4; // Taproot (P2TR)
            if (address.startsWith("tltc1q")) return 1; // Native SegWit (P2WPKH)
            if (address.startsWith("Q") || address.startsWith("R") || address.startsWith("2"))
                return 3; // Nested SegWit (P2SH-P2WPKH)
            if (address.startsWith("m") || address.startsWith("n")) return 2; // Legacy (P2PKH)
            return 0; // Unknown
        }

        // --- MAINNET ---
        else {
            if (address.startsWith("ltc1p")) return 4; // Taproot (P2TR)
            if (address.startsWith("ltc1q")) return 1; // Native SegWit (P2WPKH)
            if (address.startsWith("M") || address.startsWith("3")) return 3; // Nested SegWit (P2SH-P2WPKH)
            if (address.startsWith("L")) return 2; // Legacy (P2PKH)
            return 0; // Unknown
        }
    }

    function getAddressTypeBtc(address) {
        // --- TESTNET ---
        if (config.network === "testnet") {
            if (address.startsWith("tb1p")) return 4; // Taproot (P2TR)
            if (address.startsWith("tb1q")) return 1; // Native SegWit (P2WPKH)
            if (address.startsWith("2")) return 3;   // Nested SegWit (P2SH-P2WPKH)
            if (address.startsWith("m") || address.startsWith("n")) return 2; // Legacy (P2PKH)
            return 0; // Unknown
        }

        // --- MAINNET ---
        else {
            if (address.startsWith("bc1p")) return 4; // Taproot (P2TR)
            if (address.startsWith("bc1q")) return 1; // Native SegWit (P2WPKH)
            if (address.startsWith("3")) return 3;    // Nested SegWit (P2SH-P2WPKH)
            if (address.startsWith("1")) return 2;    // Legacy (P2PKH)
            return 0; // Unknown
        }
    }



    useEffect(() => {
        fetchAdminSettings();
    }, []);

    const fetchAdminSettings = async () => {
        try {
            let params = {
                url: "admin-Settings",
                method: "POST",
            };
            const response = await makeApiRequest(params);
            // console.log("response from admin settings", response);

            if (response.status && response.adminData) {
                const data = response.adminData;

                setInitialSettings({
                    evm_address: data.evm_address || "",
                    evm_key: data.evm_key || "",
                    btc_address: data.btc_address || "",
                    btc_publicKey: data.btc_publicKey || "",
                    sol_address: data.sol_address || "",
                    sol_key: data.sol_key || "",
                    ltc_address: data.ltc_address || "",
                    ltc_key: data.ltc_key || "",
                    ada_address: data.ada_address || "",
                    ada_key: data.ada_key || "",
                });

                setEvmAddress(data.evm_address || "");
                setEvmKey(data.evm_key || "");
                setBtcAddress(data.btc_address || "");
                setBtcKey(data.btc_publicKey || "");
                setSolAddress(data.sol_address || "");
                setSolKey(data.sol_key || "");
                setLtcAddress(data.ltc_address || "");
                setLtcKey(data.ltc_key || "");
                setAdaAddress(data.ada_address || "");
                setAdaKey(data.ada_key || "");


            }
        } catch (error) {
            toast.error("Failed to fetch admin settings");
        } finally {
            setLoading(false);
        }
    };

    const getAddressFromPrivateKey = (privateKey) => {
        try {
            const account = web3.eth.accounts.privateKeyToAccount(`0x${privateKey}`);
            return account.address.toLowerCase();
        } catch (error) {
            console.error('Error deriving address:', error.message);
        }
    };

    const getAddressFromCardanoPhrase = async (seed) => {
        try {

            const entropy = bip39.mnemonicToEntropy(seed);
            const rootKey = CardanoWasm.Bip32PrivateKey.from_bip39_entropy(
                Buffer.from(entropy, "hex"),
                Buffer.from("")
            );

            const accountKey = rootKey
                .derive(1852 | 0x80000000)
                .derive(1815 | 0x80000000)
                .derive(0 | 0x80000000);

            const paymentKey = accountKey.derive(0).derive(0);
            const paymentPubKey = paymentKey.to_public();
            const stakeKey = accountKey.derive(2).derive(0);
            const stakePubKey = stakeKey.to_public();

            const paymentCred = CardanoWasm.Credential.from_keyhash(paymentPubKey.to_raw_key().hash());
            const stakeCred = CardanoWasm.Credential.from_keyhash(stakePubKey.to_raw_key().hash());

            const baseAddr = CardanoWasm.BaseAddress.new(0, paymentCred, stakeCred);
            const address = baseAddr.to_address().to_bech32();
            return address;
        } catch (error) {
            console.error(error);
        }
    };


    const validate = async () => {
        const newErrors = {};

        // EVM
        if (!evmAddress.trim()) newErrors["evm_address"] = "EVM Address is required";
        else if (!evmRegex.test(evmAddress)) newErrors["evm_address"] = "Invalid EVM address";

        if (!evmKey.trim()) newErrors["evm_key"] = "EVM Key is required";
        else {
            try {
                const derivedEvm = getAddressFromPrivateKey(await decryptionKey(evmKey));
                if (derivedEvm !== evmAddress.toLowerCase()) {
                    newErrors["evm_address"] = "The address does not match your private key";
                }
            } catch (error) {
                console.log(error)
                newErrors["evm_key"] = "Invalid EVM key";
            }
        }

        // BTC
        if (!btcAddress.trim()) newErrors["btc_address"] = "BTC Address is required";
        else if (!btcRegex.test(btcAddress)) newErrors["btc_address"] = "Invalid BTC address";
        else if(getAddressTypeBtc(btcAddress) == 4) newErrors["btc_address"] = "Does not accept this address format";

        if (!btcKey.trim()) newErrors["btc_publicKey"] = "BTC Private Key is required";
        else {
            try {
                const derivedBtcHex = await decryptionKey(btcKey);
                const keyPair = ECPair.fromWIF(derivedBtcHex, config.bitcoinNetwork);

                const addressType = getAddressTypeBtc(btcAddress);
                let AdminAddress;
                if (addressType == 2) {
                    const { address } = bitcoin.payments.p2pkh({
                        pubkey: keyPair.publicKey,
                        network: config.bitcoinNetwork,
                    });
                    AdminAddress = address
                } else if (addressType == 1) {
                    const { address } = bitcoin.payments.p2wpkh({
                        pubkey: keyPair.publicKey,
                        network: config.bitcoinNetwork,
                    });
                    AdminAddress = address;
                } else if (addressType == 3) {
                    const p2wpkh = bitcoin.payments.p2wpkh({ pubkey: keyPair.publicKey, network: config.bitcoinNetwork });
                    const p2sh = bitcoin.payments.p2sh({ redeem: p2wpkh, network: config.bitcoinNetwork });
                    AdminAddress = p2sh.address;
                }
                else if (addressType == 4) {
                    // console.log(keyPair,"keypair>>>>>>>>")
                    // const xOnlyPubkey = keyPair.publicKey.slice(1, 33);
                    // const { address } = bitcoin.payments.p2tr({
                    //     internalPubkey: xOnlyPubkey,
                    //     network: config.bitcoinNetwork,
                    // });
                    // AdminAddress = address;
                    AdminAddress = ""
                }
                if(AdminAddress == ""){
                    newErrors["btc_address"] = "Does not accept this address format";
                }else if(AdminAddress.toLowerCase() !== btcAddress.toLowerCase()) {
                    newErrors["btc_address"] = "The address does not match your private key";
                }
            } catch (err) {
                console.log(err)
                newErrors["btc_publicKey"] = "Invalid BTC private key (must be 64 hex characters)";
            }

        }


        // // SOL
        if (!solAddress.trim()) newErrors["sol_address"] = "SOL Address is required";
        else if (!solRegex.test(solAddress)) newErrors["sol_address"] = "Invalid SOL address";

        if (!solKey.trim()) newErrors["sol_key"] = "SOL Private Key is required";
        else {
            try {
                const derivedSolKey = await decryptionKey(solKey);
                let secretKeyBytes;
                // if (/^[0-9a-fA-F]+$/.test(derivedSolKey) && derivedSolKey.length === 128) {
                secretKeyBytes = Uint8Array.from(Buffer.from(derivedSolKey, 'hex'));
                // } else {
                //     const decoded = bs58.decode(derivedSolKey);

                //     if (decoded.length !== 64) {
                //         throw new Error('Base58 decoded key is not 64 bytes');
                //     }

                //     secretKeyBytes = Uint8Array.from(Buffer.from(decoded, 'hex'));
                // }

                const kp = SolanaKeypair.fromSecretKey(secretKeyBytes);
                if (kp.publicKey.toBase58().toLowerCase() !== solAddress.toLowerCase()) {
                    newErrors["sol_address"] = "The address does not match your private key";
                }

            } catch (e) {
                console.log(e);
                newErrors["sol_key"] = "Invalid SOL private key (should be base58)";
            }
        }

        // // LTC
        if (!ltcAddress.trim()) newErrors["ltc_address"] = "LTC Address is required";
        else if (!ltcRegex.test(ltcAddress)) newErrors["ltc_address"] = "Invalid LTC address";
        else if(getAddressTypeltc(ltcAddress) == 4) newErrors["ltc_address"] = "Does not accept this address format";

        if (!ltcKey.trim()) newErrors["ltc_key"] = "LTC Private Key is required";
        else {
            try {
                const derivedLtcHex = await decryptionKey(ltcKey);
                const keyPair = ECPair.fromWIF(derivedLtcHex, config.litecoinNative);

                const addressType = getAddressTypeltc(ltcAddress);
                // console.log(addressType)
                let AdminAddress;
                if (addressType == 2) {
                    const { address } = bitcoin.payments.p2pkh({
                        pubkey: keyPair.publicKey,
                        network: config.litecoinNative,
                    });
                    AdminAddress = address
                } else if (addressType == 1) {
                    const { address } = bitcoin.payments.p2wpkh({
                        pubkey: keyPair.publicKey,
                        network: config.litecoinNative,
                    });
                    AdminAddress = address;
                } else if (addressType == 3) {
                    const p2wpkh = bitcoin.payments.p2wpkh({ pubkey: keyPair.publicKey, network: config.litecoinNative });
                    const p2sh = bitcoin.payments.p2sh({ redeem: p2wpkh, network: config.litecoinNative });
                    AdminAddress = p2sh.address;
                }
                else if (addressType == 4) {
                    // const xOnlyPubkey = keyPair.publicKey.slice(1, 33);
                    // const { address } = bitcoin.payments.p2tr({
                    //     internalPubkey: xOnlyPubkey,
                    //     network: config.litecoinNative,
                    // });
                    AdminAddress = "";
                }
                 if(AdminAddress == ""){
                    newErrors["ltc_address"] = "Does not accept this address format";
                }else if (AdminAddress.toLowerCase() !== ltcAddress.toLowerCase()) {
                    newErrors["ltc_address"] = "The address does not match your private key";
                }
            } catch (err) {
                console.log(err)
                newErrors["ltc_key"] = "Invalid LTC private key (must be 64 hex characters)";
            }

        }


        // // ADA
        if (!adaAddress.trim()) newErrors["ada_address"] = "ADA Address is required";
        else if (!adaRegex.test(adaAddress)) newErrors["ada_address"] = "Invalid ADA address";

        if (!adaKey.trim()) newErrors["ada_key"] = "ADA Secret Phrase is required";
        else {
            try {
                const derivedSeed = await decryptionKey(adaKey);
                const address = await getAddressFromCardanoPhrase(derivedSeed);
                if (address.toLowerCase() !== adaAddress.toLowerCase()) {
                    newErrors["ada_address"] = "The address does not match your secret phrase";
                }
            } catch (e) {
                console.log(e);
                newErrors["ada_key"] = "Invalid ADA secret phrase";
            }
        }

        setErrors(newErrors);
        return newErrors;
    };





    const handleSubmit = async (e) => {
        e.preventDefault();
        const validationErrors = await validate();
        // console.log(validationErrors);

        if (Object.keys(validationErrors).length > 0) {
            setLoadingStatus(false);
            return;
        }

        const currentValues = {
            evm_address: evmAddress,
            evm_key: evmKey,
            btc_address: btcAddress,
            btc_publicKey: btcKey,
            sol_address: solAddress,
            sol_key: solKey,
            ltc_address: ltcAddress,
            ltc_key: ltcKey,
            ada_address: adaAddress,
            ada_key: adaKey,
        };

        const address = await axios.get("https://api.ipify.org/?format=json");
        const lastloginIpAddress = address.data.ip;
        const ipaddress = lastloginIpAddress;

        const payload = {};
        for (const key in currentValues) {
            // console.log("key", key); 

            if (currentValues[key] !== initialSettings[key]) {
                payload[key] = currentValues[key];
            }
        }

        const payloadWithIp = { ...payload, ip: ipaddress };
        if (Object.keys(payload).length > 0) {
            // console.log("payload", payload); 

            setLoadingStatus(true);
            const encryptedData = await encryptData(payloadWithIp);
            // console.log("encryptedData",encryptedData);


            const requestedData = {
                data: encryptedData
            }
            // console.log("requestedData", requestedData); 



            let params = {
                url: "admin-Settings",
                method: "POST",
                data: requestedData,
            };


            try {
                const adminSettingres = await makeApiRequest(params);
                // console.log(adminSettingres, "adminSettingres");  


                if (adminSettingres.status) {
                    toast.success(adminSettingres.message);
                    setLoadingStatus(false);

                    fetchAdminSettings();
                } else {
                    toast.error(adminSettingres.message);
                    setLoadingStatus(false);

                }
            } catch (error) {
                console.log(error, "error in admin setting");
                setLoadingStatus(false);
            }
        }
    };

    const handleSol = async (e, setValue) => {
        const input = e.target.value;
        setValue(input);

        try {
            const decoded = bs58.decode(input);
            if (decoded.length !== 64) {
                throw new Error('Base58 decoded key is not 64 bytes');
            }

            setValue(Buffer.from(decoded).toString('hex'));
        } catch (error) {
            // console.log(error);
        }
    };



    const renderInput = (label, value, setValue, name) => (
        <div className="mb-3 row" key={name}>
            <label className="form-label">{label}:</label>
            <div className="">
                <input
                    type="text"
                    value={value}
                    onChange={(e) => {
                        if (name === "sol_key") {
                            handleSol(e, setValue);
                        } else {
                            setValue(e.target.value);
                        }
                    }}

                    className={`form-control px-2 ${errors[name] ? "is-invalid" : ""}`}
                    placeholder={label}
                />
                {errors[name] && (
                    <div className="invalid-feedback d-block">
                        {errors[name]}
                    </div>
                )}
            </div>
        </div>
    );


    if (loading) return <div style={{ marginLeft: "45vw" }}><Spinner animation="border" /> </div>;

    return (
        <>
            <ToastContainer />
            <div className="container-fluid pb-5">
                <div className="row">
                    <div className="col-lg-12">
                        <h2>Admin Setting</h2>
                        <div className="row">
                            <div className="col-lg-6">
                                <div className="setting-tabs mt-4">
                                    <form onSubmit={handleSubmit}>
                                        {renderInput("ETH Address", evmAddress, setEvmAddress, "evm_address")}
                                        {renderInput("ETH Key", evmKey, setEvmKey, "evm_key")}
                                        {renderInput("BTC Address", btcAddress, setBtcAddress, "btc_address")}
                                        {renderInput("BTC Key", btcKey, setBtcKey, "btc_publicKey")}
                                        {renderInput("SOL Address", solAddress, setSolAddress, "sol_address")}
                                        {renderInput("SOL Key", solKey, setSolKey, "sol_key")}
                                        {renderInput("LTC Address", ltcAddress, setLtcAddress, "ltc_address")}
                                        {renderInput("LTC Key", ltcKey, setLtcKey, "ltc_key")}
                                        {renderInput("ADA Address", adaAddress, setAdaAddress, "ada_address")}
                                        {renderInput("ADA Secret Phrase", adaKey, setAdaKey, "ada_key")}
                                        {/* {loadingStatus ? ( */}
                                        {/* <div class="spinner-border" role="status">
                                                <span class="visually-hidden">Loading...</span>
                                            </div> */}
                                        {/* ) : ( */}
                                        <div className="mt-4">
                                            <button type="submit" className="custom-nav-button-1 active">Submit</button>
                                        </div>
                                        {/* )} */}
                                    </form>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}

